require "vendor/autoload.php";
use PhpOffice\PhpSpreadsheet\Shared\StringHelper as S;
use PhpOffice\PhpSpreadsheet\Style\NumberFormat as NF;
$cases = [
 ["1.4", 1.4, NF::FORMAT_GENERAL, ".", ""],
 ["1004.5", 1004.5, NF::FORMAT_GENERAL, ".", ""],
 ["1000000.5", 1000000.5, NF::FORMAT_GENERAL, ".", ""],
 ["1234.56", 1234.56, NF::FORMAT_GENERAL, ".", ""],
 ["1,4", 1.4, NF::FORMAT_GENERAL, ",", "."],
 ["1.234,56", 1234.56, NF::FORMAT_GENERAL, ",", "."],
 ["1 234,56", 1234.56, NF::FORMAT_GENERAL, ",", " "],
 ["1002.50", 1002.5, NF::FORMAT_NUMBER_COMMA_SEPARATED1, ".", ""],
 ["1.002,50", 1002.5, NF::FORMAT_NUMBER_COMMA_SEPARATED1, ",", "."],
 ["1 002,50", 1002.5, NF::FORMAT_NUMBER_COMMA_SEPARATED1, ",", " "],
 ["2.50", 2.5, NF::FORMAT_NUMBER_00, ".", ""],
 ["2,50", 2.5, NF::FORMAT_NUMBER_00, ",", "."],
 ["1 234,56", 1234.56, "#,##0.00", ",", " "],
 ["12.345,68", 12345.68, "#,##0.00", ",", "."],
 ["12345.68", 12345.68, "#,##0.00", ".", ""],
];
foreach ($cases as [$exp,$v,$f,$d,$t]) {
 S::setDecimalSeparator($d); S::setThousandsSeparator($t);
 $r = NF::toFormattedString($v,$f);
 printf("%-12s %-12s got=%-12s %s (d=%s t=%s)\n", $exp, $f, $r, $exp===$r?"OK":"FAIL", $d, $t);
}
'""'

